BASE=Path(__file__).resolve().parents[1]
OUT=BASE/'deliverables';OUT.mkdir(exist_ok=True)
font_pairs=[('/System/Library/Fonts/Supplemental/Arial.ttf','/System/Library/Fonts/Supplemental/Arial Bold.ttf'),('/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf','/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf'),('C:/Windows/Fonts/arial.ttf','C:/Windows/Fonts/arialbd.ttf')]
fonts=next(((a,b) for a,b in font_pairs if Path(a).exists() and Path(b).exists()),None)
if fonts is None:raise SystemExit('Installer Arial ou DejaVu Sans et adapter font_pairs avant de générer les rapports.')
