styles=getSampleStyleSheet()
for name,size,leading,color in [('Body',10.2,14.4,'#26354b'),('TitleX',25,29,'#173a67'),('H',14,18,'#1c4f91'),('SmallX',8.5,11.5,'#52657b')]:
 styles.add(ParagraphStyle(name,fontName='ArialB' if name in ['TitleX','H'] else 'Arial',fontSize=size,leading=leading,textColor=colors.HexColor(color),spaceAfter=9))
BLUE=colors.HexColor('#245fbd');LIGHT=colors.HexColor('#edf3fb');BORDER=colors.HexColor('#d9e2ef')

def p(text,style='Body'):return Paragraph(text.replace('₂','2'),styles[style])
def h(text):return p(text,'H')
def table(headers,rows,widths):
 data=[[p(escape(str(x)),'SmallX') for x in headers]]+[[p(escape(str(x)),'SmallX') for x in row] for row in rows]
 t=Table(data,colWidths=widths,hAlign='LEFT')
 t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),LIGHT),('VALIGN',(0,0),(-1,-1),'TOP'),('LINEBELOW',(0,0),(-1,0),.8,BLUE),('LINEBELOW',(0,1),(-1,-1),.35,BORDER),('LEFTPADDING',(0,0),(-1,-1),7),('RIGHTPADDING',(0,0),(-1,-1),7),('TOPPADDING',(0,0),(-1,-1),7),('BOTTOMPADDING',(0,0),(-1,-1),5)]))
 return t

def footer(canvas,doc):
 canvas.setStrokeColor(BORDER);canvas.line(42,40,553,40);canvas.setFont('Arial',8);canvas.setFillColor(colors.HexColor('#52657b'))
 canvas.drawString(42,27,'FraudLab / ECE MSc 2 IA / Préparation de remise du 23 novembre 2026')
 canvas.drawRightString(553,27,str(doc.page))

def make(path,story):
 doc=SimpleDocTemplate(str(path),pagesize=(595.28,841.89),leftMargin=42,rightMargin=42,topMargin=39,bottomMargin=52,title=path.stem,author='Ahmed, Meriem, Flavio')
 doc.build(story,onFirstPage=footer,onLaterPages=footer)

class Architecture(Flowable):
 def __init__(self):super().__init__();self.width=510;self.height=150
 def draw(self):
  c=self.canv;c.setFont('Arial',8.5)
  for y,labels in [(103,['Train autorisé','DDPM','Augmentation','Détecteur']),(32,['Analyste','Interface / API','Score et LLM','Revue / SQLite'])]:
   for i,label in enumerate(labels):
    x=i*130;c.setFillColor(LIGHT);c.setStrokeColor(BORDER);c.rect(x,y,118,34,fill=1,stroke=1);c.setFillColor(colors.HexColor('#173a67'));c.drawCentredString(x+59,y+13,label)
    if i<3:
     c.setStrokeColor(BLUE);c.line(x+118,y+17,x+128,y+17);c.line(x+125,y+20,x+128,y+17);c.line(x+125,y+14,x+128,y+17)
  c.setFillColor(colors.HexColor('#52657b'));c.drawString(0,83,'Apprentissage hors ligne et expériences figées')
  c.drawString(0,12,'Utilisation locale, contrôle des entrées et journal de preuve')

s=[p('C2 / Cadrage du projet','SmallX'),p('Fraude bancaire, diffusion et Multi-LLM','TitleX'),p('Génération de transactions et assistance à l’analyse des alertes.'),p('Ahmed, Meriem, Flavio. Interlocuteur et contributions réelles à renseigner. Scénario métier pédagogique hypothétique autorisé. Les échéances restent à confirmer.','SmallX'),h('1. Besoin et périmètre'),p('L’utilisateur cible est un analyste chargé de revoir des alertes de transactions par carte. Le projet étudie l’utilité de données synthétiques pour la détection et l’apport de rapports factuels produits puis vérifiés par des modèles de langage.'),p('Le jeu anonymisé ne décrit pas le type précis de fraude, le marchand ou l’historique client. Le périmètre se limite donc à une détection supervisée sur labels disponibles et à la revue de faits accessibles.'),h('Fonctionnement actuel proposé'),table(['Étape / acteur','Information / risque','Minutes AS IS / cible'],[['Réception / système','Champs autorisés ; schéma invalide','0,01 / 0,01'],['Score / détecteur','Variables ; faux négatif','0,02 / 0,02'],['Alerte / supervision','Score ; surcharge','0,02 / 0,02'],['Examen / analyste','Dossier ; interprétation excessive','3 / 2,25'],['Recherche / analyste','Sources ; information absente','1,5 / 0,75'],['Synthèse / analyste','Faits ; hallucination','1,25 / 0,75'],['Validation / responsable','Avis ; absence de trace','0,5 / 0,5']],[145,216,150]),p('Hypothèses par alerte, 24 000 alertes/an. Travail humain : 6,25 min avant, 4,25 min cible avant revue ajoutée ; +0,5 min de revue = 4,75 min. Coût à 45 EUR/h : 4,69 EUR avant et 3,56 EUR après. Aucune durée bancaire observée. Détail dans docs/29_processus_metier.csv.','SmallX'),h('Irritants à confirmer'),p('Trois difficultés motivent l’étude. La rareté des fraudes limite les exemples d’apprentissage. Les fausses alertes mobilisent l’analyste. Les informations manquantes et la rédaction peuvent allonger la revue. Leur impact métier n’a pas été observé en banque.'),PageBreak()]
s+=[p('C2 / Choix de solution','SmallX'),h('2. Alternatives et justification'),table(['Approche','Apport','Question à tester'],[['Processus actuel / règles','Référence explicite','Couverture des cas'],['ML sur données originales','Score appris','Erreurs sur classe rare'],['Pondération / rééchantillonnage','Référence simple et économique','Utilité face à la diffusion'],['Augmentation par diffusion','Nouveaux vecteurs de transactions','Qualité, diversité et utilité aval'],['Mono puis Multi-LLM','Rapport et contrôle factuel','Fiabilité, coût et latence']],[145,175,191]),p('Le détecteur reste identique entre méthodes d’augmentation afin d’isoler leur effet. Le DDPM répond à l’exigence d’expérimentation diffusion. Les LLM répondent à une tâche distincte de restitution factuelle. Leur valeur doit être comparée à un rapport déterministe.'),h('Parcours cible'),p('L’analyste sélectionne une transaction autorisée. L’API valide les champs, prépare les variables et calcule un score. Le rapport affiche uniquement les faits disponibles. Une vérification indépendante signale les écarts de contrat. L’utilisateur consigne son avis et retrouve la trace dans le journal.'),h('Hypothèses de confirmation future'),p('<b>H1 valeur.</b> Viser un gain d’au moins 0,01 d’AP face à la référence pondérée sur un nouveau jeu indépendant. Ce seuil est un objectif pédagogique défini après l’expérience exploratoire et ne vaut pas préenregistrement des résultats existants.'),p('<b>H2 exploitation.</b> Viser un p95 d’inférence inférieur à 5 secondes hors chargement et un coût technique récurrent inférieur à 0,35 € par demande. La revue ajoutée est budgétée séparément. Ces seuils restent des objectifs à confirmer sur une charge définie.'),p('Le scénario central suppose deux minutes brutes gagnées par alerte et 0,5 minute de revue ajoutée. Il faut mesurer ces durées sur des dossiers comparables avant toute conclusion métier.'),PageBreak()]
s+=[p('C2 / Architecture et données','SmallX'),h('3. Architecture progressive'),Architecture(),table(['Brique','Choix du POC','Responsabilité'],[['Interface','Application web locale','Saisie, résultats, erreurs et revue'],['API','FastAPI, schémas Pydantic','Validation, score et orchestration'],['Modèles','Logistique, DDPM, deux LLM','Détection, génération et rapports'],['Stockage','SQLite, fichiers versionnés','Avis, sorties, versions et traces'],['Évaluation','Scripts et configurations figées','Métriques et reproduction']],[86,150,275]),h('Données et séparation'),p('OpenML 1597 version 1 fournit 284 807 transactions, dont 492 fraudes. L’audit retire 1 081 doublons exacts et conserve 283 726 lignes, dont 473 fraudes. Le fichier correspond à l’empreinte publiée. Le champ de licence OpenML indique « Public » ; les modalités détaillées de redistribution restent à préciser.'),table(['Partition chronologique','Transactions','Fraudes'],[['Entraînement',170235,342],['Validation',56745,57],['Test final',56746,74]],[251,130,130]),p('Les horodatages égaux restent groupés. Les transformations utilisent le train. Le détecteur reçoit V1 à V28 et log1p(Amount). Le label est exclu des rapports LLM. Les composantes PCA, la courte période et l’absence d’identifiants clients interprétables limitent la généralisation.','SmallX'),PageBreak()]
s+=[p('C2 / Valeur et coûts','SmallX'),h('4. Business case hypothétique'),p('Toutes les valeurs financières sont des hypothèses pédagogiques, sans observation bancaire. Le scénario représente 24 000 alertes/an, un coût horaire de 45 €, un investissement initial de 15 000 €, aucun gain annexe et 1 000 € d’autres coûts métier annuels.'),table(['Hypothèse','Pessimiste','Central','Optimiste'],[['Minutes brutes gagnées',0.5,2,2.5],['Minutes de revue ajoutées',0.75,0.5,0.25],['Exploitation annuelle','10 000 €','8 000 €','7 000 €']],[211,100,100,100]),table(['Exploitation EUR/an','Pess.','Centre','Optim.'],[['Calcul / matériel / énergie',1200,800,600],['Maintenance',4000,3200,2800],['Supervision technique',2500,2000,1800],['Stockage / sauvegardes',800,600,400],['Licences',0,0,0],['Réserve incidents techniques',1500,1400,1400]],[241,90,90,90]),p('Réserve technique distincte de la revue métier. Reprises métier supposées 20/10/5 %, incluses dans les minutes de revue. Centre : 666,67 EUR/mois. Ventilation initiale et sources hypothétiques dans docs/29_couts_et_processus_detail.md.','SmallX'),h('Méthode de calcul'),p('Gain brut = volume × minutes gagnées / 60 × coût horaire.<br/>Gain net opérationnel = gain brut + autres gains − revue ajoutée − autres coûts métier.<br/>Coût année 1 = investissement + exploitation.<br/>ROI année 1 = (gain net opérationnel − coût année 1) / coût année 1 × 100.'),table(['Scénario','Gain net/an','Coût année 1','ROI année 1'],[['Pessimiste','−5 500 €','25 000 €','−122,00 %'],['Central','26 000 €','23 000 €','+13,04 %'],['Optimiste','39 500 €','22 000 €','+79,55 %']],[131,130,130,120]),p('Centre : gain brut 36 000 EUR, revue 9 000 EUR et autres coûts métier 1 000 EUR. Solde année 1 : 3 000 EUR ; rentabilité à environ 1,83 min gagnée/alerte. Le scénario pessimiste est déficitaire. Aucun gain réel n’est démontré.','SmallX'),PageBreak()]
s+=[p('C2 / Validation et risques','SmallX'),h('5. Protocole et décisions'),p('Comparer les mêmes partitions et le même détecteur avec données originales, pondération, suréchantillonnage simple et ajout DDPM. Deux ratios et trois seeds sont exécutés. Choisir configurations et seuils sur validation, puis figer la décision avant le test final. Comparer les LLM seuls et la chaîne sur les mêmes cas d’une expérience.'),table(['Risque','Effet','Contrôle'],[['Fuite entre partitions','Gain surestimé','Audit, séparation et transformations sur train'],['Mémorisation','Copie d’exemples','Proximité et doublons, sans garantie de confidentialité'],['Sortie synthétique invalide','Données inutilisables','Rejets explicites et nombre d’ajouts apparié'],['Invention LLM','Rapport erroné','Faits traçables, contrat et revue humaine'],['Coût / latence','Usage peu viable','Temps mesurés, scénarios et seuils à confirmer'],['Accès / licence','Usage inadapté','Manifeste et données brutes hors dépôt']],[132,139,240]),h('Deux pistes scientifiques'),p('Ho, Jain et Abbeel, <i>Denoising Diffusion Probabilistic Models</i>, 2020, arXiv:2006.11239v2.<br/><link href="https://arxiv.org/abs/2006.11239v2" color="#245fbd">arxiv.org/abs/2006.11239v2</link>','SmallX'),p('Kotelnikov et al., <i>TabDDPM</i>, ICML 2023, PMLR 202, p. 17564-17579.<br/><link href="https://proceedings.mlr.press/v202/kotelnikov23a.html" color="#245fbd">proceedings.mlr.press/v202/kotelnikov23a.html</link>','SmallX'),p('L’analyse détaillée relie les méthodes au code et distingue notre DDPM gaussien de TabDDPM. Les premiers résultats ne démontrent pas la supériorité de la diffusion et révèlent des erreurs LLM. Le rendu conserve ces limites et la décision argumentée.'),h('Livrables et points à compléter'),p('Dépôt ou dossier unique, scripts, configurations, cas, résultats, schéma et tableaux financiers. Interlocuteur, contributions, annotation humaine et modalités finales restent à compléter. Les scénarios métier et carbone restent hypothétiques. Les dates de remise sont celles confirmées par l’enseignant.','SmallX')]
make(OUT/'C2_Cadrage_FraudLab.pdf',s)

s=[p('C3 / Première preuve technique','SmallX'),p('Diffusion tabulaire et utilité aval','TitleX'),p('Résultats exécutés et limites. Hypothèse exploratoire, système reproductible et comparaison à une baseline.'),h('1. Hypothèse et protocole'),p('Tester si un DDPM appris sur les fraudes peut générer des vecteurs utilisables pour enrichir l’entraînement d’un détecteur. Les données de train contiennent 170 235 transactions, dont 342 fraudes. La validation comporte 56 745 transactions, dont 57 fraudes. Les indices sont chronologiques et les transformations apprises utilisent le train.'),p('Le détecteur est une régression logistique, C=1, max_iter=2 000. Les références sont les données originales, la pondération et le suréchantillonnage aléatoire. La diffusion utilise un MLP 128-128, 100 pas, un schedule bêta linéaire de 0,0001 à 0,15, Adam à 0,001 et 2 000 mises à jour. Les seeds sont 17, 42 et 73. Deux ratios visés d’ajout, x1 et x4, sont testés.'),p('Le générateur reçoit 29 variables, V1 à V28 et log1p(Amount). Il réserve 20 % des fraudes de train à un contrôle interne exclu de son apprentissage. Les baselines d’ajout reçoivent exactement le nombre de synthétiques acceptés.'),h('2. Résultats sur validation'),table(['Configuration','AP moyenne','Écart-type seeds'],[['Original', '0,6236','0,0000'],['Pondération','0,7532','0,0000'],['Suréchantillonnage x1','0,6934','0,0174'],['Suréchantillonnage x4','0,7088','0,0053'],['DDPM x1','0,6720','0,0261'],['DDPM x4','0,6836','0,0442']],[251,130,130]),p('Moyennes et écarts-types calculés à partir des mesures. La dispersion nulle des références déterministes ne supprime pas l’incertitude statistique. Sur dix cas internes de seed 42, la MSE de prédiction du bruit passe de 0,9919 avec bruit prédit nul à 0,3120 avec le réseau appris. Cette mesure ne démontre pas l’utilité métier.','SmallX'),PageBreak()]
s+=[p('C3 / Erreur, décision et preuves','SmallX'),h('3. Incident reproductible'),p('Seed 42, ratio x4, 71 sorties sur 1 368 sont rejetées par le contrôle de validité, notamment pour log-montant négatif. Les générations acceptées sont sauvegardées. Le filtre est explicite et la référence de suréchantillonnage reçoit le même nombre d’ajouts. Une représentation du montant à support adapté constitue une hypothèse de correction à tester dans un nouveau protocole.'),p('Aucun quasi-doublon au seuil standardisé 1e-6 n’a été observé dans les sorties acceptées. Ce contrôle ne démontre pas la confidentialité. La classe rare et l’anonymisation limitent l’apprentissage et l’interprétation.'),h('4. Décision et résultat ultérieur figé'),p('La référence pondérée a été choisie sur validation. Le test final ultérieur, conservé à l’écart de cette sélection, contient 56 746 transactions dont 74 fraudes. À seed 42, son AP vaut 0,7442 contre 0,7551 pour DDPM x4. L’intervalle bootstrap de l’écart couvre zéro, de −0,0601 à +0,0843. La supériorité de la diffusion n’est pas établie.'),p('La décision conserve le détecteur pondéré dans le POC et documente l’absence de preuve de gain. Le test final n’est pas réévalué à chaque modification. Les résultats métier et le ROI restent hypothétiques.'),h('5. Preuves et reproduction'),table(['Élément','Emplacement dans le projet'],[['Code et configuration','src/run_experiment.py ; configs/experiment_v1.json'],['Dix cas de bruitage / débruitage','tests/cases.csv ; tests/denoising_trace.json'],['Résultats et générations','experiments/v1 ; experiments/results.csv'],['Test final figé','experiments/final_test'],['Données et droits','data/manifest.md ; docs/05_audit_donnees.md'],['POC et vérifications','src/app.py ; experiments/application_checks_reproduction.json']],[175,336]),p('Le nouvel environnement Python sur le même Mac a reproduit les 18 exécutions et les scores de validation sans écart. Les entrées publiques ont été réutilisées et revérifiées. Le benchmark LLM et le test final n’ont pas été répétés lors de cette reproduction.'),p('Les résultats de cette fiche sont mesurés ou calculés à partir des traces. Les corrections proposées sont encore hypothétiques. Les responsables et contributions du groupe restent à renseigner. Références scientifiques dans le cadrage C2.','SmallX')]
